const actors:{n:number;id:string;role:string;business:string;outlet:string}[]=[],initial:CloudRecord[]=[];let lastError='';
async function insert(records:CloudRecord[]){await db.transaction(async sql=>{for(const r of records){const keys=Object.keys(r.values);await sql.query(`insert into public.${r.table}(${keys.join(',')}) values(${keys.map((_,i)=>'$'+(i+1)).join(',')})`,Object.values(r.values));}});}
async function asRole<T>(n:number|null,role:'authenticated'|'service_role'|'anon',query:string,args:unknown[]=[]){return db.transaction(async sql=>{await sql.exec('set local role '+role);await sql.query("select set_config('request.jwt.claims',$1,true)",[JSON.stringify({role,...(n?{sub:uid(n)}:{}),user_metadata:{role:'owner'}})]);return (await sql.query<T>(query,args)).rows;});}
function store(beforeFinish?:(args:Record<string,unknown>)=>Promise<void>){return createCommandStore('https://database.test','sb_publishable_test_only',async(url,options)=>{
 const name=new URL(String(url)).pathname.split('/').at(-1)!,args=JSON.parse(options?.body as string),headers=new Headers(options?.headers),service=headers.get('apikey')==='sb_secret_test_only';
 const parameters:Record<string,string[]>={admit_stock_batch:['p_outlet_id'],prepare_stock_write:['p_id','p_ticket_id','p_type','p_outlet_id','p_plan','p_hash','p_occurred_at'],finish_stock_write:['p_ticket_id','p_token','p_records']};
 expect(parameters[name]).toBeDefined();if(service){expect(headers.has('Authorization')).toBe(false);await beforeFinish?.(args);}else expect(headers.get('apikey')).toBe('sb_publishable_test_only');
 try{const result=await asRole<{data:unknown}>(service?null:Number(headers.get('Authorization')!.split('.')[1]),service?'service_role':'authenticated',`select public.${name}(${parameters[name].map((_,i)=>'$'+(i+1)).join(',')}) data`,parameters[name].map(k=>['p_plan','p_records'].includes(k)?JSON.stringify(args[k]):args[k]));return new Response(JSON.stringify(result[0].data));}
 catch(error){const {code,message,detail:details}=error as {code:string;message:string;detail?:string};lastError=code+': '+message;return new Response(JSON.stringify({code,details}),{status:code==='42501'?403:['PT409','23505'].includes(code)?409:code==='PT429'?429:['22023','23514'].includes(code)?400:500});}
 },{serviceKey:'sb_secret_test_only'});}
function request(c:unknown,header?:string){return new Request('https://api.test/commands',{method:'POST',headers:{Origin:origin,Authorization:'Bearer user.1.signature','Content-Type':'application/json',...(header?{[stockBatchHeader]:header}:{})},body:JSON.stringify(c)});}
async function http(n:number,c:unknown,beforeFinish?:(args:Record<string,unknown>)=>Promise<void>,header?:string){const req=request(c,header??((c as StockCommand).type==='stock.batch'?(c as StockCommand).outletId:undefined));req.headers.set('Authorization',`Bearer user.${n}.signature`);return createCommandsHandler({origins:new Set([origin]),store:store(beforeFinish)})(req);}
function base(){return {id:newInboxId(),outletId:source.snapshot.outlet.id,occurredAt:Date.now()-1000};}
function input():StockSaveInput{return {name:'New rice '+literal,nameLocal:literal,unit:'kg',category:'Food',aliases:[literal],onHand:20.125,target:30,packSize:1.5,lowAt:5,supplierId:supplier.id};}
function create():Extract<StockCommand,{type:'stock.create'}>{return {...base(),type:'stock.create',stockItemId:newInboxId(),moveId:newInboxId(),input:input()};}
function adjust(item=seed,reason:'used'|'received'|'count'|'waste'='used',quantity=2):Extract<StockCommand,{type:'stock.adjust'}>{return {...base(),type:'stock.adjust',moveId:newInboxId(),change:{id:item.id,revision:item.revision,reason,quantity,source:'manual',note:literal}};}
function update(item=seed,onHand=item.onHand):Extract<StockCommand,{type:'stock.update'}>{return {...base(),type:'stock.update',stockItemId:item.id,revision:item.revision,moveId:onHand!==item.onHand?newInboxId():null,input:{...input(),name:item.name,onHand,supplierId:item.supplierId??null}};}
function archive(item=seed,restore=false):StockCommand{return {...base(),type:restore?'stock.restore':'stock.archive',stockItemId:item.id,revision:item.revision};}
function batch(items=[seed,second],count=true,quantity=0):Extract<StockCommand,{type:'stock.batch'}>{const b=base();return {...b,type:'stock.batch',count,batchId:count?newInboxId():null,changes:items.map((s,i)=>({id:s.id,revision:s.revision,reason:count?'count':'used',quantity,source:count?'count':'quick_update',note:literal,eventId:i===0?b.id:newInboxId(),moveId:newInboxId()}))};}
async function accepted(c:StockCommand,n=1){const r=await http(n,c);expect(r.status,lastError+' '+await r.clone().text()).toBe(200);return parseStockCommandReceipt(await r.json(),c);}
async function item(id=seed.id){return decodeCommandRecord('stockItems',JSON.parse((await db.query<{data:string}>('select row_to_json(s)::text data from public.stock_items s where id=$1',[id])).rows[0].data)) as unknown as StockItem;}
async function moves(id=seed.id){return (await db.query<{data:string}>('select row_to_json(m)::text data from public.stock_moves m where stock_item_id=$1 order by revision',[id])).rows.map(r=>decodeCommandRecord('stockMoves',JSON.parse(r.data)) as unknown as StockMove);}
async function counts(){return (await db.query<{items:number;moves:number;events:number;receipts:number}>("select (select count(*)::int from public.stock_items) items,(select count(*)::int from public.stock_moves) moves,(select count(*)::int from public.events) events,(select count(*)::int from private.shop_command_receipts) receipts")).rows[0];}
async function prepare(c:StockCommand,n=1){return (await asRole<{data:Record<string,unknown>}>(n,'authenticated','select public.prepare_stock_write($1,$2,$3,$4,$5,$6,$7) data',[c.id,newInboxId(),c.type,c.outletId,JSON.stringify(stockWritePlan(c)),await stockFingerprint(c),c.occurredAt]))[0].data;}
async function finish(p:Record<string,unknown>,c:StockCommand,modify?:(records:CloudRecord[])=>void){const f=stockWriteFields(p,c,p.ticketId as string);modify?.(f.p_records as CloudRecord[]);return asRole<{data:unknown}>(null,'service_role','select public.finish_stock_write($1,$2,$3) data',[f.p_ticket_id,f.p_token,JSON.stringify(f.p_records)]);}
beforeAll(async()=>{
 db=await PGlite.create();for(const f of ['supabase-auth.sql','supabase-storage.sql'])await db.exec(readFileSync(new URL('./fixtures/'+f,import.meta.url),'utf8'));
 const dir=new URL('../supabase/migrations/',import.meta.url);for(const f of readdirSync(dir).filter(f=>f.endsWith('.sql')).sort())await db.exec(readFileSync(new URL(f,dir),'utf8'));
 for(const n of [1,2,3,4,5,6])await db.query('insert into auth.users(id,phone,phone_confirmed_at) values($1,$2,now())',[uid(n),'1415555010'+n]);
 const cfg={businessType:'corner_shop' as const,marketCode:'BD' as const,name:'Stock',phone:'01712345482'};source=setupCommand(cfg);branch=setupCommand({...cfg,name:'Branch'});foreign=setupCommand({...cfg,name:'Foreign'});branch.snapshot.business=source.snapshot.business;branch.snapshot.outlet.businessId=source.snapshot.business.id;branch.snapshot.owner={...source.snapshot.owner,outletIds:[branch.snapshot.outlet.id]};
 for(const [s,n,skip] of [[source,1,false],[branch,1,true],[foreign,4,false]] as const){const tables=emptyBackupTables();tables.businesses.push(s.snapshot.business);tables.outlets.push(s.snapshot.outlet);tables.members.push(s.snapshot.owner);const plan=await prepareCloudMigration(createBackup(tables),uid(n));await insert(plan.records.filter(r=>!(skip&&['businesses','members','member_outlets'].includes(r.table))));}
 actors.push({n:1,id:source.snapshot.owner.id,role:'owner',business:source.snapshot.business.id,outlet:source.snapshot.outlet.id},{n:4,id:foreign.snapshot.owner.id,role:'owner',business:foreign.snapshot.business.id,outlet:foreign.snapshot.outlet.id});
 for(const [n,role,outlet] of [[2,'manager',source.snapshot.outlet.id],[3,'manager',branch.snapshot.outlet.id],[5,'staff',source.snapshot.outlet.id],[6,'agent',source.snapshot.outlet.id]] as const){const id=newInboxId();await db.query('insert into public.members(id,business_id,auth_user_id,name,role,created_at,updated_at) values($1,$2,$3,$4,$5,1,1)',[id,source.snapshot.business.id,uid(n),'"Person"',role]);actors.push({n,id,role,business:source.snapshot.business.id,outlet});}
 const at=Date.now()-1000,own=saveSupplierCommand({name:'Fresh '+literal,phone:'',note:literal},source.snapshot,null,0,at),other=saveSupplierCommand({name:'Branch only',phone:'',note:''},branch.snapshot,null,0,at);supplier=own.supplier;otherSupplier=other.supplier;
 for(const [s,snap] of [[own,source.snapshot],[other,branch.snapshot]] as const)initial.push(encodeCommandRecord('suppliers',s.supplier,snap.business.id),encodeCommandRecord('events',s.event,snap.business.id));
 for(const [snap,name,unit] of [[source.snapshot,literal,'kg'],[source.snapshot,'Oil','L'],[branch.snapshot,'Branch stock','kg'],[foreign.snapshot,'Foreign stock','kg']] as const){const ctx:StockContext={setup:snap,items:[],moves:[],suppliers:[supplier]},change=saveStockItemCommand({name,unit,onHand:20,target:30,packSize:1,lowAt:5},ctx,null,0,at);if(snap.outlet.id===source.snapshot.outlet.id){if(!seed)seed=change.items[0];else second=change.items[0];}else if(snap.outlet.id===branch.snapshot.outlet.id)branchItem=change.items[0];initial.push(...change.items.map(s=>encodeCommandRecord('stockItems',s,snap.business.id)),...change.moves.map(m=>encodeCommandRecord('stockMoves',m,snap.business.id)),...change.events.map(e=>encodeCommandRecord('events',e,snap.business.id)));}
},30_000);
beforeEach(async()=>{lastError='';await db.exec("delete from private.stock_command_resolutions;delete from private.stock_review_tickets;truncate public.suppliers,public.stock_items,public.events cascade;delete from private.stock_write_tickets;update auth.users set phone='1415555010'||right(id::text,1),phone_confirmed_at=now(),banned_until=null,deleted_at=null;update public.members set active=true");for(const a of actors){await db.query('update public.members set role=$1,auth_user_id=$2 where id=$3',[a.role,uid(a.n),a.id]);await db.query('delete from public.member_outlets where member_id=$1',[a.id]);await db.query('insert into public.member_outlets values($1,$2,$3)',[a.business,a.id,a.outlet]);}await insert(initial);});
