// These review cases use the same native SQL database, real HTTP adapters and
// explicit synthetic Auth boundary as the ordinary command cases above.
function stockReviewPacket(command:StockCommand,change:StockChange):StockReviewRequest{command=parseStockCommand(command);return {id:newInboxId(),replacementId:newInboxId(),command,sourceHash:'a'.repeat(64),sourceJson:JSON.stringify({v:1,entryId:newInboxId(),sequence:1,commandIndex:0,at:command.occurredAt,events:stockReviewSourceAudits(command,change.events)})};}
async function stockReviewAdjustment(reason:'count'|'received'|'used'='count',quantity=2.125,n=1){const ctx:StockContext={setup:{...source.snapshot,owner:{...source.snapshot.owner,id:actors.find(a=>a.n===n)!.id}},items:[await item(),await item(second.id)],moves:await moves(),suppliers:[supplier]},change=adjustStockCommand({id:ctx.items[0].id,revision:ctx.items[0].revision,reason,quantity,note:literal},ctx,Date.now()-10);return stockReviewPacket(stockAdjustmentIntent(change),change);}
function stockReviewGateway(beforeRpc?:(name:string,args:Record<string,unknown>)=>Promise<void>){
 return createStockReviewStore('https://database.test','sb_publishable_test_only','sb_secret_test_only',async(url,options)=>{
  const name=new URL(String(url)).pathname.split('/').at(-1)!,args=JSON.parse(options?.body as string),headers=new Headers(options?.headers),service=headers.get('apikey')==='sb_secret_test_only';
  const parameters:Record<string,string[]>={admit_stock_review:['p_outlet_id'],inspect_stock_outcome:['p_command_id','p_type','p_outlet_id','p_hash'],prepare_stock_review:['p_id','p_replacement_id','p_command_id','p_type','p_outlet_id','p_plan','p_hash','p_occurred_at','p_intent_json','p_source_hash','p_source_json','p_unit_facts'],read_stock_review:['p_id','p_token'],prepare_stock_write:['p_id','p_ticket_id','p_type','p_outlet_id','p_plan','p_hash','p_occurred_at'],finish_stock_review:['p_id','p_token','p_outcome','p_replacement_ticket','p_replacement_token','p_replacement_hash','p_replacement_records']};
  expect(parameters[name],name).toBeDefined();expect(service).toBe(name==='finish_stock_review');if(service)expect(headers.has('Authorization')).toBe(false);await beforeRpc?.(name,args);
  try{const result=await asRole<{data:unknown}>(service?null:Number(headers.get('Authorization')!.split('.')[1]),service?'service_role':'authenticated',`select public.${name}(${parameters[name].map((_,i)=>'$'+(i+1)).join(',')}) data`,parameters[name].map(k=>['p_plan','p_unit_facts','p_replacement_records'].includes(k)?JSON.stringify(args[k]):args[k]));return Response.json(result[0].data);}
  catch(error){const {code,message}=error as {code:string;message:string};lastError=code+': '+message;return Response.json({code},{status:code==='42501'?403:['PT409','23505'].includes(code)?409:code==='PT429'?429:['22023','23514','22P02'].includes(code)?400:500});}
 });
}
async function stockReviewHttp(p:StockReviewRequest,decision?:{token:string;outcome:'withdrawn'|'replaced'},n=1,beforeRpc?:(name:string,args:Record<string,unknown>)=>Promise<void>){return createStockReviewHandler({store:stockReviewGateway(beforeRpc),origins:new Set([origin])})(new Request('https://api.test/commands?review=stock-'+(decision?'resolve':'read'),{method:'POST',headers:{Origin:origin,Authorization:`Bearer user.${n}.signature`,'Content-Type':'application/json',[commandReviewHeader]:p.command.outletId},body:JSON.stringify(decision?{...p,...decision}:p)}));}
async function stockReviewRead(p:StockReviewRequest,n=1){const r=await stockReviewHttp(p,undefined,n);expect(r.status,lastError+' '+await r.clone().text()).toBe(200);return (await r.json()).review as PreparedStockReview;}
async function stockReviewResolve(p:StockReviewRequest,v:PreparedStockReview,outcome:'withdrawn'|'replaced'='replaced',n=1){const r=await stockReviewHttp(p,{token:v.token,outcome},n);expect(r.status,lastError+' '+await r.clone().text()).toBe(200);return parseStockResolutionReceipt(await r.json(),p.command);}
