 const p=await stockReviewAdjustment(),v=await stockReviewRead(p),before=await counts(),r=await stockReviewHttp(p,{token:v.token,outcome:'replaced'},1,async(name,args)=>{if(name==='prepare_stock_write')(args.p_plan as {rows:{revision:number}[]}).rows[0].revision++;});expect(r.status,lastError).toBe(400);expect(await counts()).toEqual(before);expect((await item()).onHand).toBe(20);
