it('native resolution audit failure rolls back its stock movement, both receipts and private archive',async()=>{
 const p=await stockReviewAdjustment(),v=await stockReviewRead(p),before=await counts();await db.exec("create function private.test_stock_review_failure() returns trigger language plpgsql as $$begin if new.command='sync.resolve' then raise exception 'synthetic audit failure';end if;return new;end$$;create trigger test_stock_review_failure before insert on public.events for each row execute function private.test_stock_review_failure()");
 try{const r=await stockReviewHttp(p,{token:v.token,outcome:'replaced'});expect(r.status,lastError).toBe(503);expect(await counts()).toEqual(before);expect((await item()).onHand).toBe(20);expect((await db.query('select id from private.stock_command_resolutions')).rows).toHaveLength(0);}finally{await db.exec('drop trigger test_stock_review_failure on public.events;drop function private.test_stock_review_failure()');}
});
it('native review keeps all 1000 maximum-escaped counts atomic without reducing the ordinary batch or deadline',async()=>{
 const ctx:StockContext={setup:source.snapshot,items:[],moves:[],suppliers:[]},records:CloudRecord[]=[];
 for(let i=0;i<1000;i++){const change=saveStockItemCommand({name:'Bulk '+i+'\0'.repeat(110),unit:'u'+'\0'.repeat(23),onHand:20,target:30,packSize:1},ctx);ctx.items.push(...change.items);ctx.moves.push(...change.moves);records.push(...change.items.map(x=>encodeCommandRecord('stockItems',x,source.snapshot.business.id)),...change.moves.map(x=>encodeCommandRecord('stockMoves',x,source.snapshot.business.id)),...change.events.map(x=>encodeCommandRecord('events',x,source.snapshot.business.id)));}
 await insert(records);const change=stockBatchCommand(ctx.items.map(item=>({id:item.id,revision:item.revision,reason:'count',quantity:0,note:'\0'.repeat(1000)})),ctx,Date.now(),true),p=stockReviewPacket(stockBatchIntent(change,true),change);expect(new TextEncoder().encode(JSON.stringify(p.command)).length).toBeLessThan(8_000_000);await accepted(adjust(ctx.items[0],'count',5));const v=await stockReviewRead(p);expect(v.proposal.enabled&&v.proposal.items).toHaveLength(1000);const before=await counts(),started=performance.now(),r=await stockReviewResolve(p,v);expect(performance.now()-started).toBeLessThan(45_000);expect(r.replacement?.receipt.results).toHaveLength(1000);expect(r.replacement?.receipt.results.every((row,i)=>row.onHand===0&&row.revision===(i===0?3:2))).toBe(true);expect((await counts()).moves-before.moves).toBe(1000);expect((await counts()).events-before.events).toBe(1001);expect((await moves(ctx.items.at(-1)!.id)).at(-1)).toMatchObject({note:'\0'.repeat(1000),countBatchId:stockWritePlan(p.command).batchId});
},120_000);
